import bpy

torus = bpy.data.objects['Torus']
action = torus.animation_data.action

fcurves = []
for layer in action.layers:
    for strip in layer.strips:
        for cbag in strip.channelbags:
            fcurves.extend(cbag.fcurves)

for fc in fcurves:
    for kp in fc.keyframe_points:
        kp.interpolation = 'LINEAR'

print('fcurves:', len(fcurves))
print('keys:', [(fc.data_path, [k.co[0] for k in fc.keyframe_points]) for fc in fcurves])

